<?php require __DIR__.'/inc/core.php';auth();if(!ekAdmin()){http_response_code(403);exit('Yönetici yetkisi gerekir.');}require __DIR__.'/inc/layout.php';$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();try{db()->exec("CREATE TABLE IF NOT EXISTS moving_content_templates (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,transport ENUM('road','sea_fcl','sea_lcl','other') NOT NULL DEFAULT 'road',language ENUM('TR','EN') NOT NULL DEFAULT 'TR',service_scope TEXT NOT NULL,transport_process TEXT NOT NULL,delivery_time TEXT NOT NULL,payment_terms TEXT NOT NULL,additional_terms TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='Şablon tablosu hazır. Mevcut teklifler değiştirilmedi.';}catch(Throwable $e){$error='Kurulum başarısız: '.h($e->getMessage());}}top('İçerik Şablonları Kurulumu');?><h1>V11.9 İçerik Şablonları Kurulumu</h1><p>Bu işlem yalnızca yeni bir şablon tablosu oluşturur; eski şablonları ve teklifleri silmez.</p><?php if($msg):?><p><?=h($msg)?></p><a href="templates.php">Şablonlara dön</a><?php endif;?><?php if($error):?><p><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button type="submit">Kurulumu Başlat</button></form><?php bottom(); ?>